### 1. Go Service Scaffold (Gin Framework)
This template sets up middleware, logging, and a structure ready for your specific handlers.

```go
package main

import (
	"log"
	"net/http"
	"os"
	"time"

	"github.com/gin-gonic/gin"
)

// Middleware: Logging & Latency Tracking
func loggerMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		start := time.Now()
		c.Next()
		latency := time.Since(start)
		log.Printf("[%d] %s %s %v", c.Writer.Status(), c.Request.Method, c.Request.URL.Path, latency)
	}
}

// Example Handler: Replace with your actual logic
func healthCheck(c *gin.Context) {
	c.JSON(http.StatusOK, gin.H{"status": "ok"})
}

// Example Handler: Replace with your actual logic
func getData(c *gin.Context) {
	// Insert business logic here
	c.JSON(http.StatusOK, gin.H{"data": "example"})
}

func main() {
	r := gin.Default()
	r.Use(loggerMiddleware())

	// --- DEFINE YOUR ROUTES HERE ---
	r.GET("/health", healthCheck)
	r.GET("/api/v1/resource", getData)
	// -------------------------------

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	log.Printf("Starting Go service on port %s", port)
	if err := r.Run(":" + port); err != nil {
		log.Fatalf("Failed to start server: %v", err)
	}
}
